'use strict';
const $=s=>document.querySelector(s);
const $app=$('#app'),$modal=$('#modal-root'),$toasts=$('#toasts');
const state={me:null,rooms:[],friends:[],online:[],messages:[],members:[],bots:[],view:'home',roomId:null,authMode:'login',search:'',people:[],draft:'',socket:null,loading:false};
const E=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const icons={house:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',chat:'<path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8A8.5 8.5 0 0 1 12.5 20a8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8A8.5 8.5 0 0 1 12.5 3h.5a8.48 8.48 0 0 1 8 8v.5z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',server:'<rect x="3" y="3" width="18" height="8" rx="2"/><rect x="3" y="13" width="18" height="8" rx="2"/><path d="M7 7h.01M7 17h.01"/>',bot:'<rect x="3" y="8" width="18" height="13" rx="3"/><path d="M12 3v5M8 3h8M8 14h.01M16 14h.01M8 18h8"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.87l.05.05-2 2-.05-.05A1.7 1.7 0 0 0 15.87 18a1.7 1.7 0 0 0-1.2 1.57V21h-3.34v-.4A1.7 1.7 0 0 0 10.12 19a1.7 1.7 0 0 0-1.87.34l-.05.05-2-2 .05-.05A1.7 1.7 0 0 0 6 15.47a1.7 1.7 0 0 0-1.57-1.2H4v-3.34h.4A1.7 1.7 0 0 0 6 9.72a1.7 1.7 0 0 0-.34-1.87l-.05-.05 2-2 .05.05A1.7 1.7 0 0 0 9.53 6a1.7 1.7 0 0 0 1.2-1.57V4h3.34v.4A1.7 1.7 0 0 0 15.28 6a1.7 1.7 0 0 0 1.87-.34l.05-.05 2 2-.05.05A1.7 1.7 0 0 0 19.4 9.53a1.7 1.7 0 0 0 1.57 1.2H21v3.34h-.4A1.7 1.7 0 0 0 19.4 15Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',send:'<path d="m22 2-7 20-4-9-9-4zM22 2 11 13"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',compass:'<circle cx="12" cy="12" r="10"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5z"/>',check:'<path d="m5 12 4 4L19 6"/>',logout:'<path d="M10 17l5-5-5-5M15 12H3M12 3h7a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-7"/>',poll:'<path d="M6 20V12M12 20V4M18 20v-9"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/>',link:'<path d="M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 1 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5M8 22h8"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/>',edit:'<path d="M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L9 17l-4 1 1-4z"/>',trash:'<path d="M3 6h18M8 6V4h8v2M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',globe:'<circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15 15 0 0 1 0 20M12 2a15 15 0 0 0 0 20"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>'};
const ic=(name,size=20)=>`<svg class="ico" style="width:${size}px;height:${size}px" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.plus}</svg>`;
const av=(p,size='')=>`<span class="avatar ${size}" style="background:${/^#[\da-f]{6}$/i.test(p.color||'')?p.color:'#7259c1'}">${p.id&&p.avatar_rev?`<img class="avatar-img" src="/api/profile-media/${Number(p.id)}/avatar?v=${Number(p.avatar_rev)}" alt="">`:E((p.display_name||p.username||'V').slice(0,1).toUpperCase())}${p.id&&state.online.includes(p.id)?'<span class="online-dot"></span>':''}</span>`;
const fmt=t=>new Date(t*1000).toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'});
const meText=()=>E(state.me?.display_name||'');
function toast(msg,error=false){const x=document.createElement('div');x.className='toast'+(error?' error':'');x.textContent=msg;$toasts.appendChild(x);setTimeout(()=>x.remove(),4000)}
async function api(path,opts={}){let o={credentials:'same-origin',...opts};if(o.body&&!(o.body instanceof FormData)){o.headers={'Content-Type':'application/json',...(o.headers||{})};o.body=JSON.stringify(o.body)}const r=await fetch('/api'+path,o);let data;try{data=await r.json()}catch{data={}}if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:'Błąd połączenia.');return data}
function authScreen(){const reg=state.authMode==='register';$app.innerHTML=`<div class="auth-root"><div class="auth-layout"><div class="auth-brand"><img class="logo" src="/static/vilo-icon.png" alt="VILO"><h1>VILO<span style="color:#9f84ff">.</span></h1><p>Twoje miejsce do rozmów, grup i wspólnych pomysłów. Prosto, nowocześnie i razem.</p><div style="margin-top:24px"><span class="pill purple">VILO Modern + Clean</span></div></div><div class="auth-box"><h2>${reg?'Utwórz konto':'Witaj ponownie!'}</h2><p>${reg?'Dołącz do VILO i zaproś znajomych.':'Zaloguj się, by wrócić do swoich rozmów.'}</p><form data-form="auth"> <div class="field"><label>${reg?'Twój nick':'Nick lub adres e-mail'}</label><input name="username" placeholder="${reg?'np. Gracz123':'Twój nick'}" minlength="3" required autocomplete="username"/></div>${reg?'<div class="field"><label>E-mail</label><input name="email" type="email" placeholder="twoj@email.pl" required autocomplete="email"/></div>':''}<div class="field"><label>Hasło</label><input name="password" type="password" minlength="8" placeholder="Minimum 8 znaków" required autocomplete="${reg?'new-password':'current-password'}"/></div><button class="primary wide" type="submit">${reg?'Utwórz konto':'Zaloguj się'} ${ic('arrow',15)}</button></form><div class="auth-toggle">${reg?'Masz już konto?':'Nie masz konta?'} <button data-action="toggle-auth">${reg?'Zaloguj się':'Zarejestruj się'}</button></div><p class="help" style="margin-top:23px">Wersja do lokalnych testów. E-mail nie jest jeszcze weryfikowany, a odzyskiwanie hasła wymaga dalszego wdrożenia. Użyj osobnego hasła testowego.</p></div></div></div>`}
function navButton(id,icon,label){let active=state.view===id || (id==='chats'&&state.view==='room'&&state.rooms.find(r=>r.id===state.roomId)?.kind==='dm')||(id==='groups'&&state.view==='room'&&state.rooms.find(r=>r.id===state.roomId)?.kind!=='dm');return `<button class="rail-btn ${active?'active':''}" data-action="nav" data-view="${id}" aria-label="${label}" title="${label}">${ic(icon,21)}</button>`}
function sidebar(){const v=state.view;let list='';let title=v==='room'?'Rozmowy':({home:'VILO Home',friends:'Znajomi',chats:'Wiadomości',groups:'Grupy i serwery',bots:'VILO Bot Studio',discover:'Odkrywaj',settings:'Ustawienia'}[v]||'VILO');if(['home','chats','groups','room','bots'].includes(v)){
  let type=v==='chats'?'dm':v==='groups'?'group':null;
  let items=state.rooms.filter(r=>(!type||(type==='group'?r.kind!=='dm':r.kind===type))&&(!state.search||r.name.toLowerCase().includes(state.search.toLowerCase())));
  list=`<div class="small-title">Twoje rozmowy · ${items.length}</div>`+items.map(r=>`<button class="side-row ${state.roomId===r.id&&state.view==='room'?'selected':''}" data-action="open-room" data-id="${r.id}">${r.kind==='dm'?av(r.other||{display_name:r.name,color:'#6956a4'}):`<span class="groupbadge">${ic(r.kind==='server'?'server':'users',19)}</span>`}<span class="side-copy"><b>${E(r.name)}</b><small>${E(r.last_message|| (r.kind==='dm'?'Prywatna rozmowa':r.member_count+' członków'))}</small></span></button>`).join('');
  if(!items.length)list+='<div class="help" style="padding:14px">Nie ma jeszcze rozmów w tej kategorii.</div>';
  list+=`<div class="small-title">Szybkie działania</div><button class="side-row" data-action="new-group">${ic('plus',18)} <span>Utwórz grupę</span></button><button class="side-row" data-action="join-group">${ic('link',18)} <span>Dołącz z zaproszenia</span></button><button class="side-row" data-action="find-users">${ic('search',18)} <span>Znajdź znajomego</span></button>`;
 }else if(v==='friends'){const f=state.friends.filter(x=>x.status==='accepted');list='<div class="small-title">Znajomi</div>'+f.map(x=>`<button class="side-row" data-action="open-dm" data-id="${x.id}">${av(x)}<span class="side-copy"><b>${E(x.display_name)}</b><small>@${E(x.username)}</small></span></button>`).join('')+`<button class="side-row" data-action="find-users">${ic('plus')} Dodaj znajomych</button>`}
 else if(v==='settings'){list=['Moje konto','Bezpieczeństwo i prywatność','Wygląd VILO','Powiadomienia','Głos i wideo','Czat i multimedia','Urządzenia i aplikacja','Dostępność'].map(x=>`<div class="side-row">${ic('settings',16)} <span>${E(x)}</span></div>`).join('')}
 else{list=`<div class="small-title">VILO</div><button class="side-row" data-action="nav" data-view="home">${ic('house')} Strona główna</button>`}
 return `<aside class="sidebar"><div class="sidebar-head"><h2>${E(title)}</h2><div class="searchbox" style="margin-top:15px">${ic('search')}<input id="side-search" placeholder="Znajdź rozmowę…" value="${E(state.search)}"></div></div><div class="sidebody" id="sidebody">${list}</div><div class="userbar">${av(state.me)}<span class="side-copy"><b>${meText()}</b><small><span style="color:var(--green)">●</span> Online</small></span><button class="ghost" data-action="nav" data-view="settings" aria-label="Ustawienia">${ic('settings',19)}</button></div></aside>`}
function head(){const r=state.rooms.find(x=>x.id===state.roomId);const v=state.view;let title=v==='room'&&r?r.name:({home:'VILO Home',friends:'Twoi znajomi',chats:'Wiadomości',groups:'Grupy i serwery',bots:'VILO Bot Studio',discover:'Odkrywaj',settings:'Ustawienia'}[v]||'VILO');let sub=v==='room'&&r?(r.kind==='dm'?'Prywatna rozmowa':`${r.member_count} członków · ${r.kind==='server'?'Serwer':'Grupa'}`):'Twoje miejsce do rozmów';let buttons=v==='room'&&r?`${r.kind!=='dm'?`<button class="soft" data-action="new-poll">${ic('poll',17)} Ankieta</button><button class="soft" data-action="invite">${ic('link',17)} Zaproś</button>`:''}`:`<button class="soft" data-action="new-group">${ic('plus',17)} Nowa grupa</button>`;
 return `<header class="mainbar"><div class="grow"><h2>${E(title)}</h2><p class="muted">${E(sub)}</p></div><div class="row">${buttons}<button class="ghost" title="Znajdź użytkownika" data-action="find-users">${ic('search',19)}</button></div></header>`}
function home(){const people=state.friends.filter(f=>f.status==='accepted');const rooms=state.rooms.filter(r=>r.kind!=='dm').slice(0,8);const recent=state.rooms.slice(0,6);return `<div class="mainview"><div class="view-width"><div class="home-welcome"><div><h1>Witaj w VILO, ${meText()} 👋</h1><p>Wszystkie rozmowy w jednym miejscu.</p></div><span class="pill purple">VILO Clean</span></div><section class="section"><div class="section-heading"><h3>Znajomi online</h3><button class="ghost" data-action="nav" data-view="friends">Wszyscy znajomi →</button></div>${people.length?`<div class="friendstrip">${people.filter(f=>state.online.includes(f.id)).map(f=>`<button class="friendchip" data-action="open-dm" data-id="${f.id}">${av(f,'round')}<span>${E(f.display_name)}</span></button>`).join('')||'<p class="muted">Nikt ze znajomych nie jest teraz online.</p>'}</div>`:`<div class="card"><p class="muted">Dodaj znajomych, a pojawią się tutaj.</p><button class="soft" style="margin-top:12px" data-action="find-users">${ic('plus',15)} Dodaj znajomego</button></div>`}</section><section class="section"><div class="section-heading"><h3>Ostatnie wiadomości</h3><button class="ghost" data-action="nav" data-view="chats">Wszystkie →</button></div>${recent.length?`<div class="cards">${recent.map(r=>`<button class="card interactive room-tile" data-action="open-room" data-id="${r.id}"><span class="groupbadge">${ic(r.kind==='dm'?'chat':'users')}</span><span class="grow"><b>${E(r.name)}</b><small>${E(r.last_message||'Otwórz rozmowę')}</small></span></button>`).join('')}</div>`:`<div class="card"><p class="muted">Nie masz jeszcze wiadomości. Utwórz grupę lub dodaj znajomych.</p></div>`}</section><section class="section"><div class="section-heading"><h3>Twoje grupy i serwery</h3><button class="ghost" data-action="nav" data-view="groups">Zobacz wszystkie →</button></div>${rooms.length?`<div class="cards">${rooms.map(r=>`<button class="card interactive room-tile" data-action="open-room" data-id="${r.id}"><span class="groupbadge">${ic(r.kind==='server'?'server':'users')}</span><span class="grow"><b>${E(r.name)}</b><small>${r.member_count} członków</small></span></button>`).join('')}</div>`:`<div class="card"><p class="muted">Twoje pierwsze grupy będą tutaj.</p><button class="soft" style="margin-top:12px" data-action="new-group">${ic('plus',15)} Utwórz grupę</button></div>`}</section></div></div>`}
function friends(){const f=state.friends;const accepted=f.filter(x=>x.status==='accepted'),incoming=f.filter(x=>x.status==='pending'&&x.direction==='incoming'),out=f.filter(x=>x.status==='pending'&&x.direction==='outgoing');return `<div class="mainview"><div class="view-width"><div class="row between page-heading"><div><h1>Znajomi</h1><p>Wszystkie kontakty i zaproszenia</p></div><button class="primary" data-action="find-users">${ic('plus',17)} Dodaj znajomego</button></div>${incoming.length?`<section class="section"><div class="section-heading"><h3>Zaproszenia do zaakceptowania (${incoming.length})</h3></div><div class="item-list">${incoming.map(x=>`<div class="item">${av(x)}<span class="grow"><b>${E(x.display_name)}</b><small>@${E(x.username)} chce dodać Cię do znajomych.</small></span><button class="primary" data-action="accept-friend" data-id="${x.friendship_id}">Akceptuj</button></div>`).join('')}</div></section>`:''}<section class="section"><div class="section-heading"><h3>Twoi znajomi (${accepted.length})</h3></div>${accepted.length?`<div class="item-list">${accepted.map(x=>`<div class="item">${av(x)}<span class="grow"><b>${E(x.display_name)}</b><small>@${E(x.username)} · ${state.online.includes(x.id)?'🟢 Online':'Offline'}</small></span><button class="soft" data-action="open-dm" data-id="${x.id}">${ic('chat',16)} Napisz</button></div>`).join('')}</div>`:`<div class="empty"><div class="emptyicon">${ic('users',29)}</div><h2>Znajomych jeszcze tu nie ma</h2><p>Wyszukaj nick znajomego i wyślij zaproszenie.</p><button class="primary" data-action="find-users">Znajdź osoby</button></div>`}</section>${out.length?`<section class="section"><h3>Wysłane zaproszenia</h3><div class="item-list" style="margin-top:10px">${out.map(x=>`<div class="item">${av(x)}<span class="grow"><b>${E(x.display_name)}</b><small>Oczekiwanie na akceptację</small></span><span class="pill">Wysłano</span></div>`).join('')}</div></section>`:''}</div></div>`}
function groups(){const list=state.rooms.filter(r=>r.kind!=='dm');return `<div class="mainview"><div class="view-width"><div class="row between page-heading"><div><h1>Grupy i serwery</h1><p>Twórz społeczności, zapraszaj znajomych i organizuj ankiety.</p></div><div class="row"><button class="soft" data-action="join-group">${ic('link',15)} Dołącz</button><button class="primary" data-action="new-group">${ic('plus',16)} Utwórz</button></div></div>${list.length?`<div class="cards">${list.map(r=>`<button class="card interactive room-tile" data-action="open-room" data-id="${r.id}"><span class="groupbadge">${ic(r.kind==='server'?'server':'users',23)}</span><span class="grow"><b>${E(r.name)}</b><small>${r.member_count} członków · ${r.role==='owner'?'Właściciel':'Członek'}</small></span></button>`).join('')}</div>`:`<div class="empty"><div class="emptyicon">${ic('users',28)}</div><h2>Stwórz własną społeczność</h2><p>Załóż grupę lub dołącz przez kod zaproszenia.</p><button class="primary" data-action="new-group">Utwórz pierwszą grupę</button></div>`}</div></div>`}
function messageView(m){let user=m.bot_name?{display_name:m.bot_name,color:'#7553b2'}:{id:m.user_id,display_name:m.display_name||m.username||'Użytkownik',color:m.color||'#544a7c',avatar_rev:m.avatar_rev||0};let actions=m.deleted?'':`<div class="msg-actions">${['👍','❤️','😂','🔥'].map(emoji=>`<button class="micro" data-action="react" data-id="${m.id}" data-emoji="${emoji}" aria-label="Reakcja ${emoji}">${emoji}</button>`).join('')}${m.user_id===state.me.id&&m.kind==='text'?`<button class="micro" data-action="edit-message" data-id="${m.id}">${ic('edit',12)} Edytuj</button>`:''}${m.user_id===state.me.id||state.rooms.find(r=>r.id===state.roomId)?.role==='owner'?`<button class="micro" data-action="delete-message" data-id="${m.id}">Usuń</button>`:''}</div>`;
 let extra=m.kind==='poll'&&m.poll?poll(m.poll):m.kind==='file'?`<a class="msg-attachment" href="/api/uploads/${encodeURIComponent(m.attachment_id)}">${ic('file',19)} <span>${E(m.attachment_name||'Załącznik')}</span> ${ic('arrow',16)}</a>`:`<p class="msgtext ${m.deleted?'deleted':''}">${m.deleted?'Wiadomość została usunięta.':E(m.body)}${m.edited?' <small>(edytowano)</small>':''}</p>`;
 return `<article class="message">${av(user)}<div class="msgbody"><div class="msghead"><b>${E(user.display_name)}</b>${m.kind==='bot'?'<span class="systembot">BOT</span>':''}<time>${fmt(m.created)}</time></div>${extra}${m.reactions?.length?`<div class="row" style="flex-wrap:wrap;margin-top:7px">${m.reactions.map(r=>`<button class="micro ${r.mine?'mine':''}" data-action="react" data-id="${m.id}" data-emoji="${E(r.emoji)}">${E(r.emoji)} ${r.count}</button>`).join('')}</div>`:''}${actions}</div></article>`}
function poll(p){return `<div class="poll"><div class="row" style="margin-bottom:9px;color:#c2b3ff;font-size:12px">${ic('poll',16)} ANKIETA</div><h3>${E(p.question)}</h3><form data-form="vote" data-id="${p.id}">${p.choices.map(x=>`<label class="option"><span class="bar" style="width:${p.total?Math.round(100*x.count/p.total):0}%"></span><input type="${p.multiple?'checkbox':'radio'}" name="option" value="${x.id}" ${p.selected.includes(x.id)?'checked':''}><span>${E(x.label)}</span><b>${x.count} gł.</b></label>`).join('')}<div class="poll-foot"><span class="muted">${p.total} głosów ${p.anonymous?'· anonimowa':''}</span><button class="soft" type="submit">Zagłosuj</button></div></form></div>`}
function roomView(){const r=state.rooms.find(x=>x.id===state.roomId);if(!r)return home();let msgs=state.messages.map(messageView).join('');let footer=`<div class="composer"><form data-form="message"><label class="ghost" title="Prześlij plik" for="upload-file">${ic('plus',21)}</label><input id="upload-file" type="file" hidden/><textarea id="message-text" rows="1" maxlength="4000" placeholder="Napisz wiadomość do ${E(r.name)}…">${E(state.draft)}</textarea><button class="primary sendbtn" title="Wyślij" type="submit">${ic('send',19)}</button></form><p class="help" style="margin-top:6px;margin-left:8px">Enter = wyślij · Shift+Enter = nowa linia · Pliki do 10 MB</p></div>`;
 let details=`<aside class="details"><h4>Członkowie (${state.members.length})</h4>${state.members.map(m=>`<div class="member">${av(m)}<span class="grow"><b>${E(m.display_name)}</b><br><span class="role">${m.role==='owner'?'Właściciel':m.role==='admin'?'Administrator':'Członek'}</span></span></div>`).join('')}${r.kind!=='dm'?`<button class="soft wide" style="margin-top:15px" data-action="invite">${ic('link',15)} Zaproś do grupy</button><h4>Boty (${state.bots.length})</h4>${state.bots.map(b=>`<div class="member">${ic('bot',18)} ${E(b.name)}</div>`).join('')||'<p class="help">Nie dodano jeszcze botów.</p>'}<button class="soft wide" style="margin-top:8px" data-action="new-bot">${ic('plus',15)} Utwórz bota</button>`:''}</aside>`;
 return `<div class="room-layout"><div class="room-main"><div class="room-content" id="message-list">${msgs||`<div class="empty"><div class="emptyicon">${ic('chat',28)}</div><h2>Początek rozmowy</h2><p>Napisz pierwszą wiadomość i rozpocznij czat.</p></div>`}</div>${footer}</div>${details}</div>`}
function bots(){const r=state.rooms.find(x=>x.id===state.roomId&&x.kind!=='dm')||state.rooms.find(x=>x.kind!=='dm');return `<div class="mainview"><div class="view-width"><div class="row between page-heading"><div><h1>VILO Bot Studio</h1><p>Twórz własne automatyczne odpowiedzi bez programowania.</p></div>${r?`<button class="primary" data-action="new-bot" data-id="${r.id}">${ic('plus',17)} Nowy bot</button>`:''}</div><div class="planned"><b>Aktualny zakres:</b> proste boty oparte na komendach, np. <code>/pomoc</code> → wiadomość. Zaawansowany edytor kodu i publiczny katalog są zaplanowane, ale nie są jeszcze dostępne.</div>${!r?`<div class="empty"><div class="emptyicon">${ic('bot',27)}</div><h2>Najpierw utwórz grupę</h2><p>Boty działają wewnątrz grup.</p><button class="primary" data-action="new-group">Utwórz grupę</button></div>`:`<p class="small-title">Boty w grupie: ${E(r.name)}</p><div class="item-list">${state.bots.length?state.bots.map(b=>`<div class="item">${ic('bot',24)}<div class="grow"><b>${E(b.name)}</b><small>${E(b.trigger)} → ${E(b.response)}</small></div><button class="soft" data-action="delete-bot" data-id="${b.id}">Usuń</button></div>`).join(''):'<div class="card"><p class="muted">Tu pojawią się boty utworzone dla wybranej grupy.</p></div>'}</div>`}</div></div>`}
function settings(){return `<div class="mainview"><div class="view-width settings-area"><div class="page-heading"><h1>Ustawienia VILO</h1><p>Twoje konto, prywatność i wygląd.</p></div><div class="card row" style="margin-bottom:20px">${av(state.me)}<div class="grow"><b>${meText()}</b><p class="muted">@${E(state.me.username)} · VILO ID ${state.me.id}</p></div><button class="primary" data-action="edit-profile">Edytuj profil</button></div>${[['user','Moje konto','Edytuj nazwę, opis profilu i kolor.','edit-profile'],['shield','Bezpieczeństwo i prywatność','Sesje i 2FA w przygotowaniu.','planned'],['settings','Wygląd VILO','VILO Modern + Clean; dodatkowe motywy w przygotowaniu.','planned'],['bell','Powiadomienia','Alerty w aplikacji, rozbudowane ustawienia później.','planned'],['mic','Głos i wideo','Rozmowy głosowe i wideo są w planie.','planned'],['chat','Czat i multimedia','Wiadomości, reakcje, ankiety i załączniki.','planned'],['server','Urządzenia i aplikacja','Aplikacja działa teraz w przeglądarce lokalnej.','planned'],['shield','Dostępność','Systemowe skalowanie oraz mniejszy ruch.','planned']].map(([icon,title,sub,act])=>`<div class="settings-row">${ic(icon,20)}<div class="grow"><b>${title}</b><small>${sub}</small></div><button class="soft" data-action="${act}" data-name="${E(title)}">${act==='planned'?'W planie':'Otwórz'}</button></div>`).join('')}<button class="soft danger" data-action="logout" style="margin-top:25px">${ic('logout',18)} Wyloguj się</button></div></div>`}
function discover(){return `<div class="mainview"><div class="view-width"><div class="page-heading"><h1>VILO Discover</h1><p>Znajdź nowe osoby i dołącz do społeczności.</p></div><div class="cards"><div class="card"><h3>Dołącz przez zaproszenie</h3><p class="muted" style="margin:8px 0 17px">Wklej kod, który wysłał Ci właściciel grupy.</p><button class="primary" data-action="join-group">${ic('link',17)} Dołącz do grupy</button></div><div class="card"><h3>Znajdź znajomego</h3><p class="muted" style="margin:8px 0 17px">Szukaj osób po nicku VILO.</p><button class="soft" data-action="find-users">${ic('search',17)} Wyszukaj</button></div></div><div class="planned">Publiczny katalog serwerów, botów i miniaplikacji będzie dostępny dopiero po wdrożeniu systemu moderacji oraz weryfikacji społeczności. Teraz działają zaproszenia i wyszukiwanie użytkowników.</div></div></div>`}
function draw(){if(!state.me){authScreen();return}let r=state.rooms.find(x=>x.id===state.roomId);let main=state.view==='home'?home():state.view==='friends'?friends():state.view==='groups'?groups():state.view==='chats'?groups():state.view==='room'?roomView():state.view==='bots'?bots():state.view==='settings'?settings():discover();const buttons=[['home','house','Home'],['chats','chat','Wiadomości'],['friends','users','Znajomi'],['groups','server','Grupy'],['bots','bot','Boty'],['discover','compass','Odkrywaj']];$app.innerHTML=`<div class="app-shell"><nav class="rail" aria-label="Nawigacja VILO"><button class="rail-btn" data-action="nav" data-view="home" title="VILO Home"><img src="/static/favicon.png" alt="VILO" class="brandicon"/></button><div class="divider"></div>${buttons.map(x=>navButton(...x)).join('')}<div class="rail-bottom">${navButton('settings','settings','Ustawienia')}<button class="rail-btn" title="Wyloguj" data-action="logout">${ic('logout')}</button></div></nav>${sidebar()}<main class="content">${head()}${main}</main><nav class="mobilebar" aria-label="Nawigacja mobilna">${[['home','house','Home'],['chats','chat','Czaty'],['groups','server','Grupy'],['friends','users','Znajomi'],['settings','settings','Ustawienia']].map(x=>navButton(...x)).join('')}</nav></div>`;if(state.view==='room'){const l=$('#message-list');if(l)l.scrollTop=l.scrollHeight}}
async function refresh(drawNow=true){if(!state.me)return;try{const [rooms,friends,online,me]=await Promise.all([api('/rooms'),api('/friends'),api('/online'),api('/me')]);state.rooms=rooms;state.friends=friends;state.online=online.ids;state.me=me;if(state.roomId){if(!rooms.some(r=>r.id===state.roomId)){state.roomId=null;state.view='home'}else{const [msgs,members,bots]=await Promise.all([api(`/rooms/${state.roomId}/messages`),api(`/rooms/${state.roomId}/members`),api(`/rooms/${state.roomId}/bots`)]);state.messages=msgs;state.members=members;state.bots=bots;}}if(drawNow)draw()}catch(e){console.error(e);toast(e.message,true)}}
function connect(){if(state.socket){try{state.socket.close()}catch{}}const proto=location.protocol==='https:'?'wss':'ws';const w=new WebSocket(`${proto}://${location.host}/ws`);state.socket=w;w.onmessage=msg=>{try{const dat=JSON.parse(msg.data);if(dat.type==='refresh'){clearTimeout(window.reloader);window.reloader=setTimeout(()=>refresh(),170)}}catch{}};w.onclose=()=>{if(state.me)setTimeout(()=>{if(state.socket===w)connect()},3500)}}
async function boot(){state.me=await api('/me');await refresh(false);draw();connect();const invite=new URLSearchParams(location.search).get('invite');if(invite){try{const res=await api('/invites/join',{method:'POST',body:{code:invite}});state.view='room';state.roomId=res.id;history.replaceState(null,'','/');await refresh();toast('Dołączono do grupy!')}catch(e){toast(e.message,true)}}}
function openModal(title,html){$modal.innerHTML=`<div class="modal-overlay" id="overlay"><section class="modal" role="dialog" aria-modal="true"><header class="modal-header"><h2>${E(title)}</h2><button class="ghost" data-action="close-modal" aria-label="Zamknij">${ic('close')}</button></header>${html}</section></div>`;setTimeout(()=>$modal.querySelector('input:not([type="checkbox"]),textarea')?.focus(),50)}
function closeModal(){$modal.innerHTML=''}
function formInput(name,label,placeholder='',value='',type='text'){return `<div class="field"><label for="f-${E(name)}">${E(label)}</label><input id="f-${E(name)}" name="${E(name)}" type="${type}" placeholder="${E(placeholder)}" value="${E(value)}" required maxlength="160"></div>`}
function modalAction(action,id){const room=state.rooms.find(x=>x.id===state.roomId);if(action==='new-group')openModal('Utwórz grupę lub serwer',`<form data-form="new-group">${formInput('name','Nazwa','np. Nasza ekipa')}<div class="field"><label>Rodzaj</label><select name="kind"><option value="group">Grupa</option><option value="server">Serwer</option></select></div><p class="help">Po utworzeniu możesz zaprosić inne osoby i dodawać ankiety.</p><div class="actions"><button class="primary" type="submit">Utwórz</button></div></form>`);
else if(action==='join-group')openModal('Dołącz do grupy',`<form data-form="join-group">${formInput('code','Kod lub link zaproszenia','Wklej otrzymany kod')}<div class="actions"><button class="primary" type="submit">Dołącz</button></div></form>`);
else if(action==='find-users')openModal('Znajdź znajomego',`<div class="field"><label>Nick użytkownika</label><input id="user-search" placeholder="Wpisz co najmniej 2 litery" autocomplete="off"></div><div id="users-results" class="item-list"><p class="help">Wyszukaj konto po nicku.</p></div>`);
else if(action==='new-poll'){if(!room||room.kind==='dm'){toast('Otwórz grupę, aby utworzyć ankietę.',true);return}openModal('Nowa ankieta',`<form data-form="new-poll">${formInput('question','Twoje pytanie','np. W co dzisiaj gramy?')}<div class="field"><label>Odpowiedzi (każda w nowej linii, 2–8)</label><textarea name="options" rows="5" required placeholder="Minecraft\nFortnite\nRoblox\nCoś innego"></textarea></div><label class="checkboxline"><input type="checkbox" name="multiple"> Pozwól zaznaczyć kilka odpowiedzi</label><label class="checkboxline"><input type="checkbox" name="anonymous"> Głosowanie anonimowe</label><div class="actions"><button class="primary" type="submit">Opublikuj ankietę</button></div></form>`)}
else if(action==='new-bot'){const rid=Number(id)||state.roomId||state.rooms.find(x=>x.kind!=='dm')?.id;const found=state.rooms.find(x=>x.id===rid);if(!found||found.kind==='dm'){toast('Najpierw wybierz grupę.',true);return}if(!['owner','admin'].includes(found.role)){toast('Tylko administrator może dodać bota.',true);return}state.roomId=rid;openModal('Nowy bot VILO',`<form data-form="new-bot">${formInput('name','Nazwa bota','np. Pomocnik')} ${formInput('trigger','Komenda','/pomoc')}<div class="field"><label>Odpowiedź bota</label><textarea name="response" rows="3" maxlength="500" required placeholder="Cześć! W czym mogę pomóc?"></textarea></div><p class="help">Bot odpowie, gdy ktoś wpisze dokładnie tę komendę na czacie grupy. Nie wykonuje dowolnego kodu.</p><div class="actions"><button type="submit" class="primary">Dodaj bota</button></div></form>`)}
else if(action==='edit-profile')openModal('Edytuj profil',`<form data-form="edit-profile"><div class="profile-edit-preview"><div class="profile-edit-banner" style="${state.me.banner_rev?`background-image:url('/api/profile-media/${Number(state.me.id)}/banner?v=${Number(state.me.banner_rev)}')`:''}"></div><div class="profile-edit-avatar">${av(state.me,'large')}</div><b>${meText()}</b><small>@${E(state.me.username)}</small></div><div class="field"><label>Zdjęcie profilowe (JPG / PNG / WebP, do 3 MB)</label><input type="file" name="avatar_file" accept="image/jpeg,image/png,image/webp,image/gif"></div><div class="field"><label>Baner profilu (do 3 MB)</label><input type="file" name="banner_file" accept="image/jpeg,image/png,image/webp,image/gif"></div>${formInput('display_name','Wyświetlana nazwa','',state.me.display_name)}<div class="field"><label>Krótki status</label><input name="status_text" maxlength="80" value="${E(state.me.status_text||'')}" placeholder="np. Gram w Minecraft"></div><div class="field"><label>Opis profilu</label><textarea name="about" maxlength="220" rows="3">${E(state.me.about)}</textarea></div><div class="field"><label>Kolor awatara bez zdjęcia</label><input type="color" name="color" value="${E(state.me.color)}" style="height:48px;width:100%"></div><div class="row" style="gap:10px;margin-top:10px"><button type="button" class="soft" data-action="delete-profile-media" data-id="avatar">Usuń awatar</button><button type="button" class="soft" data-action="delete-profile-media" data-id="banner">Usuń baner</button></div><p class="help">Zdjęcia zostaną zapisane lokalnie na serwerze testowym VILO.</p><div class="actions"><button type="submit" class="primary">Zapisz profil</button></div></form>`)
else if(action==='invite'){if(!room||room.kind==='dm'){toast('Wybierz grupę.',true);return}if(!['owner','admin'].includes(room.role)){toast('Tylko administrator może utworzyć zaproszenie.',true);return}api(`/rooms/${room.id}/invites`,{method:'POST'}).then(x=>{const link=`${location.origin}/?invite=${encodeURIComponent(x.code)}`;openModal('Zaproś do grupy',`<p class="muted" style="margin-bottom:14px">Link jest ważny przez 7 dni i ma limit 30 użyć. Działa, jeśli odbiorca może połączyć się z serwerem VILO.</p><div class="field"><label>Link zaproszenia</label><input id="invite-link" readonly value="${E(link)}"></div><div class="actions"><button class="primary" data-action="copy-invite">${ic('copy',16)} Kopiuj link</button></div>`)}).catch(e=>toast(e.message,true))}
else if(action==='edit-message'){const m=state.messages.find(x=>x.id===Number(id));if(!m)return;openModal('Edytuj wiadomość',`<form data-form="edit-message" data-id="${m.id}"><div class="field"><label>Treść wiadomości</label><textarea name="body" rows="4" maxlength="4000" required>${E(m.body)}</textarea></div><div class="actions"><button class="primary" type="submit">Zapisz</button></div></form>`)}
else if(action==='planned'){toast('Ta funkcja jest w planie i nie działa jeszcze w tej wersji.')} }
async function handleAction(el){let a=el.dataset.action,id=el.dataset.id;try{if(a==='toggle-auth'){state.authMode=state.authMode==='login'?'register':'login';draw()}
else if(a==='close-modal')closeModal();else if(a==='nav'){state.view=el.dataset.view;state.search='';if(state.view==='bots'){const room=state.rooms.find(x=>x.id===state.roomId&&x.kind!=='dm')||state.rooms.find(x=>x.kind!=='dm');if(room){state.roomId=room.id;const [b,m]=await Promise.all([api(`/rooms/${room.id}/bots`),api(`/rooms/${room.id}/members`)]);state.bots=b;state.members=m}}draw()}
else if(a==='open-room'){state.roomId=Number(id);state.view='room';state.draft='';await refresh()}
else if(a==='open-dm'){const res=await api(`/dm/${id}`,{method:'POST'});state.roomId=res.id;state.view='room';state.draft='';await refresh()}
else if(['new-group','join-group','find-users','new-poll','new-bot','edit-profile','invite','edit-message','planned'].includes(a))modalAction(a,id||el.dataset.name)
else if(a==='accept-friend'){await api(`/friends/${id}/accept`,{method:'POST'});toast('Zaproszenie zaakceptowane.');await refresh()}
else if(a==='friend-request'){await api(`/friends/request/${id}`,{method:'POST'});toast('Zaproszenie wysłane.');closeModal();await refresh()}
else if(a==='copy-invite'){const input=$('#invite-link');if(input){try{await navigator.clipboard.writeText(input.value);toast('Link skopiowany!')}catch{input.select();toast('Zaznaczono link. Skopiuj go ręcznie.')}}}
else if(a==='react'){await api(`/messages/${id}/react`,{method:'POST',body:{emoji:el.dataset.emoji}});await refresh()}
else if(a==='delete-message'){if(confirm('Usunąć tę wiadomość?')){await api(`/messages/${id}`,{method:'DELETE'});await refresh()}}
else if(a==='delete-bot'){if(confirm('Usunąć bota?')){await api(`/rooms/${state.roomId}/bots/${id}`,{method:'DELETE'});await refresh()}}
else if(a==='logout'){await api('/logout',{method:'POST'});state.me=null;state.rooms=[];state.roomId=null;state.socket?.close();state.socket=null;draw();toast('Wylogowano.')}}catch(e){toast(e.message,true)}}
async function handleForm(e){const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const type=form.dataset.form;const fd=new FormData(form);const val=k=>String(fd.get(k)||'').trim();try{if(type==='auth'){await api(state.authMode==='login'?'/login':'/register',{method:'POST',body:{username:val('username'),password:val('password'),email:val('email')||null}});await boot();toast('Witaj w VILO!')}
else if(type==='new-group'){const x=await api('/rooms',{method:'POST',body:{name:val('name'),kind:val('kind')}});closeModal();state.roomId=x.id;state.view='room';await refresh();toast('Grupa została utworzona!')}
else if(type==='join-group'){const x=await api('/invites/join',{method:'POST',body:{code:val('code')}});closeModal();state.roomId=x.id;state.view='room';await refresh();toast('Dołączono do grupy!')}
else if(type==='message'){const msg=val('body')||val('message')||state.draft.trim();if(!msg)return;await api(`/rooms/${state.roomId}/messages`,{method:'POST',body:{body:msg}});state.draft='';await refresh()}
else if(type==='new-poll'){const options=val('options').split('\n').map(s=>s.trim()).filter(Boolean);await api(`/rooms/${state.roomId}/polls`,{method:'POST',body:{question:val('question'),options,multiple:!!fd.get('multiple'),anonymous:!!fd.get('anonymous')}});closeModal();state.view='room';await refresh();toast('Ankieta opublikowana!')}
else if(type==='vote'){const ids=Array.from(form.querySelectorAll('input[name=option]:checked')).map(x=>Number(x.value));await api(`/polls/${form.dataset.id}/vote`,{method:'POST',body:{option_ids:ids}});await refresh();toast('Głos zapisany.')}
else if(type==='new-bot'){await api(`/rooms/${state.roomId}/bots`,{method:'POST',body:{name:val('name'),trigger:val('trigger'),response:val('response')}});closeModal();await refresh();toast('Bot został utworzony!')}
else if(type==='edit-profile'){
 await api('/me',{method:'PATCH',body:{display_name:val('display_name'),about:val('about'),color:val('color'),status_text:val('status_text')}});
 for(const kind of ['avatar','banner']){
   const file=fd.get(kind+'_file');
   if(file instanceof File&&file.size){const media=new FormData();media.append('file',file);await api('/me/media/'+kind,{method:'POST',body:media})}
 }
 closeModal();await refresh();toast('Profil zapisany!');
 }
else if(type==='edit-message'){await api(`/messages/${form.dataset.id}`,{method:'PATCH',body:{body:val('body')}});closeModal();await refresh();toast('Wiadomość zmieniona!')}}catch(err){toast(err.message,true)}}
function mount(){document.addEventListener('click',e=>{if(e.target.id==='overlay')closeModal();const el=e.target.closest('[data-action]');if(el){e.preventDefault();handleAction(el)}});document.addEventListener('submit',handleForm);document.addEventListener('input',e=>{if(e.target.id==='message-text')state.draft=e.target.value;if(e.target.id==='side-search'){state.search=e.target.value;const x=document.activeElement;const pos=x.selectionStart;const scroll=$('#sidebody')?.scrollTop||0;const html=sidebar();const temp=document.createElement('div');temp.innerHTML=html;$('.sidebar').replaceWith(temp.firstElementChild);const inp=$('#side-search');inp.focus();inp.setSelectionRange(pos,pos);$('#sidebody').scrollTop=scroll}if(e.target.id==='user-search'){clearTimeout(window.searchTimer);window.searchTimer=setTimeout(async()=>{const q=e.target.value.trim();if(q.length<2){$('#users-results').innerHTML='<p class="help">Wpisz co najmniej 2 znaki.</p>';return}try{const users=await api('/users?q='+encodeURIComponent(q));const container=$('#users-results');if(!container)return;container.innerHTML=users.length?users.map(u=>`<div class="item">${av(u)}<div class="grow"><b>${E(u.display_name)}</b><small>@${E(u.username)}</small></div><button class="soft" data-action="friend-request" data-id="${u.id}">${ic('plus',15)} Zaproś</button></div>`).join(''):'<p class="help">Nie znaleziono użytkownika.</p>'}catch(err){toast(err.message,true)}},290)}});document.addEventListener('keydown',e=>{if(e.target.id==='message-text'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.target.form?.requestSubmit()}if(e.key==='Escape')closeModal()});document.addEventListener('change',async e=>{if(e.target.id==='upload-file'&&e.target.files?.length){const file=e.target.files[0];if(file.size>10*1024*1024){toast('Plik nie może przekraczać 10 MB.',true);return}const fd=new FormData();fd.append('file',file);try{await api(`/rooms/${state.roomId}/upload${state.channels.length?`?channel_id=${state.channelId}`:''}`,{method:'POST',body:fd});await refresh();toast('Plik wysłany.')}catch(err){toast(err.message,true)}}})}
// VILO Server Studio extension — uses the existing authenticated app and API.
const safeStore={getItem:k=>{try{return window.localStorage.getItem(k)}catch{return null}},setItem:(k,v)=>{try{window.localStorage.setItem(k,v)}catch{}}};
state.channels=[];
state.channelId=null;
state.showChannels=false;
state.studio=null;
state.roles={roles:[],mine:[]};
state.accent=safeStore.getItem('vilo_accent')||'#9070ff';
state.theme=safeStore.getItem('vilo_theme')||'dark';
state.compact=safeStore.getItem('vilo_compact')==='1';
function applyAppearance(){
  document.documentElement.dataset.theme=state.theme;
  document.documentElement.dataset.compact=state.compact?'yes':'no';
  document.documentElement.style.setProperty('--purple',state.accent);
  document.documentElement.style.setProperty('--purple2',state.accent);
}
applyAppearance();
const oldSidebar=sidebar;
sidebar=function(){
 const room=state.rooms.find(r=>r.id===state.roomId);
 if(state.view!=='room'||room?.kind!=='server')return oldSidebar();
 let byCategory={};
 for(const ch of state.channels){(byCategory[ch.category||'TEKSTOWE']??=[]).push(ch)}
 const cats=Object.entries(byCategory).map(([cat,list])=>`<section class="channels-category"><div class="category-heading"><span>${E(cat)}</span>${state.studio?.can_manage_channels?`<button class="tiny-btn" title="Nowy kanał" data-action="new-channel">＋</button>`:''}</div>${list.map(ch=>`<div class="channel-row-wrap"><button class="channel-row ${state.channelId===ch.id?'chosen':''}" data-action="open-channel" data-id="${ch.id}"><span class="channel-symbol">${ch.kind==='voice'?'◉':ch.kind==='announcement'?'✦':'#'}</span><span>${E(ch.name)}</span>${ch.staff_only?'<span class="mini-lock">●</span>':''}</button>${state.studio?.can_manage_channels?`<button class="channel-edit" data-action="edit-channel" data-id="${ch.id}" title="Ustawienia kanału">${ic('settings',14)}</button>`:''}</div>`).join('')}</section>`).join('');
 return `<aside class="sidebar server-sidebar ${state.showChannels?'show':''}"><div class="sidebar-head"><div class="row between"><h2>${E(room.name)}</h2><button class="ghost" title="Ustawienia serwera" data-action="server-settings">${ic('settings',18)}</button></div><p class="server-subtitle">${E(room.description||'Twoja społeczność w VILO')}</p></div><div class="sidebody"><button class="side-row rule-link" data-action="show-rules">${ic('shield',18)} <span>Regulamin serwera</span></button>${cats}<div class="channels-footer"><button class="side-row" data-action="invite">${ic('link',17)} Zaproś znajomych</button>${state.studio?.can_manage_channels?`<button class="side-row" data-action="new-channel">${ic('plus',17)} Dodaj kanał</button>`:''}</div></div><div class="userbar">${av(state.me)}<span class="side-copy"><b>${meText()}</b><small>● Online</small></span><button class="ghost" data-action="nav" data-view="settings" title="Ustawienia">${ic('settings',19)}</button></div></aside>`;
};
const oldHead=head;
head=function(){
 const room=state.rooms.find(r=>r.id===state.roomId);
 if(state.view!=='room'||room?.kind!=='server')return oldHead();
 const ch=state.channels.find(x=>x.id===state.channelId);
 return `<header class="mainbar"><button class="ghost mobile-only" data-action="toggle-channels" title="Kanały">${ic('server',18)}</button><div class="grow"><h2>${ch?`${ch.kind==='voice'?'◉':'#'} ${E(ch.name)}`:E(room.name)}</h2><p class="muted">${ch?.kind==='announcement'?'Ogłoszenia serwera':ch?.kind==='voice'?'Kanał głosowy — rozmowy zostaną dodane później':`${room.member_count} członków · ${E(ch?.category||'Serwer VILO')}`}</p></div><div class="row header-actions"><button class="soft" data-action="show-rules">${ic('shield',16)} Regulamin</button>${ch?.kind!=='voice'?`<button class="soft" data-action="new-poll">${ic('poll',16)} Ankieta</button>`:''}<button class="soft" data-action="invite">${ic('link',16)} Zaproś</button>${state.studio?.can_manage?`<button class="ghost" title="Ustawienia serwera" data-action="server-settings">${ic('settings',19)}</button>`:''}</div></header>`;
};
const oldRoomView=roomView;
roomView=function(){
 const room=state.rooms.find(r=>r.id===state.roomId);
 if(room?.kind!=='server')return oldRoomView();
 const ch=state.channels.find(x=>x.id===state.channelId);
 const isVoice=ch?.kind==='voice';
 const isAnnouncement=ch?.kind==='announcement';
 const canSend=!isVoice&&(!isAnnouncement||state.studio?.can_manage_channels);
 const body=isVoice?`<div class="feature-placeholder"><div class="emptyicon">${ic('mic',32)}</div><h2>${E(ch.name)}</h2><p>Ten kanał jest przygotowany w strukturze serwera. Rozmowy głosowe nie są jeszcze obsługiwane w tej wersji.</p></div>`:state.messages.length?state.messages.map(messageView).join(''):`<div class="channel-empty"><span class="channel-big">#</span><h2>Witaj na kanale #${E(ch?.name||'ogólny')}</h2><p>Tu zaczyna się rozmowa. Napisz pierwszą wiadomość.</p></div>`;
 const composer=canSend?`<div class="composer"><form data-form="message"><label class="ghost" title="Wyślij plik" for="upload-file">${ic('plus',21)}</label><input id="upload-file" type="file" hidden><textarea id="message-text" rows="1" maxlength="4000" placeholder="Wiadomość na #${E(ch?.name||'ogólny')}…">${E(state.draft)}</textarea><button class="primary sendbtn" type="submit" title="Wyślij">${ic('send',19)}</button></form><p class="help" style="margin-top:6px;margin-left:8px">Enter — wyślij · Shift+Enter — nowa linia</p></div>`:`<div class="read-only-note">${isVoice?'Kanał głosowy: obsługa rozmów w przygotowaniu.':'Tylko administracja może wysyłać ogłoszenia.'}</div>`;
 const people=state.members.map(m=>`<div class="member">${av(m)}<span class="grow"><b>${E(m.display_name)}</b><br><span class="role">${m.role==='owner'?'Właściciel':m.role==='admin'?'Administrator':(m.custom_roles||[]).map(id=>state.roles.roles.find(r=>r.id===id)?.name).filter(Boolean).join(', ')||'Członek'}</span></span>${state.studio?.room?.owner_id===state.me.id&&m.id!==state.me.id?`<button class="ghost" data-action="assign-role" data-id="${m.id}" title="Przypisz role">${ic('settings',15)}</button>`:''}</div>`).join('');
 const details=`<aside class="details"><h4>ONLINE / CZŁONKOWIE · ${state.members.length}</h4>${people||'<p class="help">Nie ma członków.</p>'}<div class="member-actions"><button class="soft wide" data-action="invite">${ic('link',15)} Zaproś</button>${state.studio?.can_manage?`<button class="soft wide" data-action="manage-roles">${ic('shield',15)} Role i uprawnienia</button>`:''}<button class="soft wide" data-action="show-rules">${ic('file',15)} Regulamin</button></div></aside>`;
 return `<div class="room-layout server-room-layout"><div class="room-main"><div class="room-content" id="message-list">${body}</div>${composer}</div>${details}</div>`;
};
const oldSettings=settings;
settings=function(){
 const themes=[{key:'dark',name:'VILO Dark',color:'#171b2c'},{key:'light',name:'VILO Light',color:'#e7eaf6'}];
 const accents=['#9070ff','#648af5','#d76da7','#2bbd9e','#e59657'];
 return `<div class="mainview"><div class="view-width settings-area"><div class="page-heading"><h1>Ustawienia VILO</h1><p>Wszystko uporządkowane w jednym miejscu.</p></div><div class="vilo-profile-card"><div class="vilo-profile-banner" style="${state.me.banner_rev?`background-image:url('/api/profile-media/${Number(state.me.id)}/banner?v=${Number(state.me.banner_rev)}')`:''}"></div><div class="vilo-profile-identity">${av(state.me,'large')}<div class="grow"><h2>${meText()}</h2><small>@${E(state.me.username)} · ${E(state.me.status_text||'Online')}</small><p>${E(state.me.about||'Dodaj opis swojego profilu.')}</p></div><button class="primary" data-action="edit-profile">Edytuj profil</button></div></div><div class="settings-section"><h3>Wygląd VILO</h3><p class="muted">Wybierz motyw, akcent i układ interfejsu.</p><div class="theme-options">${themes.map(t=>`<button data-action="set-theme" data-id="${t.key}" class="theme-card ${state.theme===t.key?'selected':''}"><span style="background:${t.color}"></span>${t.name}</button>`).join('')}</div><div class="accent-swatches">${accents.map(a=>`<button aria-label="Akcent ${a}" title="Wybierz kolor" class="accent-swatch ${state.accent===a?'selected':''}" style="background:${a}" data-action="set-accent" data-id="${a}"></button>`).join('')}</div><label class="checkboxline"><input type="checkbox" id="toggle-compact" ${state.compact?'checked':''}> Tryb kompaktowy — więcej miejsca na wiadomości</label></div>${[['shield','Bezpieczeństwo i prywatność','Konto, zgłoszenia i prywatność; 2FA wymaga dalszego wdrożenia.'],['bell','Powiadomienia','Powiadomienia w aplikacji; reguły będą rozwijane.'],['mic','Głos i wideo','Funkcje głosowe nie są jeszcze dostępne.'],['chat','Czat i multimedia','Wiadomości, ankiety, reakcje, boty i pliki do 10 MB.'],['server','Urządzenia i aplikacja','Wersja Windows i lokalny backend — nie uruchamiaj publicznie.'],['shield','Dostępność','Zalecane skalowanie systemowe, ograniczanie animacji.']].map(([i,title,sub])=>`<div class="settings-row">${ic(i,20)}<span class="grow"><b>${title}</b><small>${sub}</small></span></div>`).join('')}<button class="soft danger" data-action="logout" style="margin-top:22px">${ic('logout',17)} Wyloguj się</button></div></div>`;
};
const baseRefresh=refresh;
refresh=async function(drawNow=true){
 if(!state.me)return;
 try{
  const [rooms,friends,online,me]=await Promise.all([api('/rooms'),api('/friends'),api('/online'),api('/me')]);
  state.rooms=rooms;state.friends=friends;state.online=online.ids;state.me=me;
  const room=rooms.find(r=>r.id===state.roomId);
  if(state.roomId&&!room){state.roomId=null;state.view='home';state.channelId=null;state.channels=[];}
  else if(room){
   if(room.kind==='server'){
     const [channels,studio,roles,members,bots]=await Promise.all([api(`/rooms/${room.id}/channels`),api(`/rooms/${room.id}/studio`),api(`/rooms/${room.id}/roles`),api(`/rooms/${room.id}/members`),api(`/rooms/${room.id}/bots`)]);
     state.channels=channels;state.studio=studio;state.roles=roles;state.members=members;state.bots=bots;
     if(!channels.some(c=>c.id===state.channelId))state.channelId=channels.find(c=>c.kind!=='voice')?.id||channels[0]?.id||null;
     state.messages=state.channelId&&channels.find(c=>c.id===state.channelId)?.kind!=='voice'?await api(`/rooms/${room.id}/messages?channel_id=${state.channelId}`):[];
   }else{
     state.channels=[];state.channelId=null;state.studio=null;state.roles={roles:[],mine:[]};
     const [msgs,members,bots]=await Promise.all([api(`/rooms/${room.id}/messages`),api(`/rooms/${room.id}/members`),api(`/rooms/${room.id}/bots`)]);
     state.messages=msgs;state.members=members;state.bots=bots;
   }
  }
  if(drawNow)draw();
 }catch(e){console.error(e);toast(e.message,true)}
};
function newChannelDialog(ch){
 if(!state.studio?.can_manage_channels)return toast('Brak uprawnień do kanałów.',true);
 openModal(ch?'Edytuj kanał':'Nowy kanał',`<form data-form="${ch?'edit-channel':'new-channel'}" ${ch?`data-id="${ch.id}"`:''}>${formInput('name','Nazwa kanału','np. pogaduchy',ch?.name||'')} ${formInput('category','Kategoria','np. TEKSTOWE',ch?.category||'TEKSTOWE')}<div class="field"><label>Rodzaj kanału</label><select name="kind"><option value="text" ${ch?.kind==='text'?'selected':''}># Kanał tekstowy</option><option value="announcement" ${ch?.kind==='announcement'?'selected':''}>✦ Ogłoszenia (pisze administracja)</option><option value="voice" ${ch?.kind==='voice'?'selected':''}>◉ Kanał głosowy (planowany)</option></select></div><label class="checkboxline"><input type="checkbox" name="staff_only" ${ch?.staff_only?'checked':''}> Prywatny kanał — tylko administracja i uprawnione role</label><div class="actions">${ch?`<button type="button" class="soft danger" data-action="delete-channel" data-id="${ch.id}">Usuń</button>`:''}<button type="submit" class="primary">${ch?'Zapisz zmiany':'Utwórz kanał'}</button></div></form>`);
}
function serverSettingsDialog(){const d=state.studio;if(!d?.can_manage){toast('Ustawienia edytuje administracja.',true);return}const r=d.room,c=d.config||{};
 openModal('Ustawienia serwera',`<div class="modal-kicker">VILO Server Studio</div><form data-form="server-settings">${formInput('name','Nazwa serwera','',r.name)}<div class="field"><label>Opis serwera</label><textarea name="description" maxlength="500" rows="2">${E(r.description)}</textarea></div><div class="field"><label>Regulamin</label><textarea name="rules" maxlength="6000" rows="7">${E(c.rules)}</textarea></div><div class="field"><label>Wiadomość powitalna</label><input name="welcome" maxlength="300" value="${E(c.welcome)}"></div><div class="field"><label>Kolor serwera</label><input type="color" name="accent" value="${E(c.accent||'#8b6cf3')}" style="height:50px"></div><div class="actions"><button type="submit" class="primary">Zapisz ustawienia</button></div></form>`);
}
function rolesDialog(){const room=state.rooms.find(x=>x.id===state.roomId);if(room?.owner_id!==state.me.id)return toast('Tylko właściciel zarządza rolami.',true);
 openModal('Role i uprawnienia',`<div class="modal-kicker">${E(room.name)}</div><div class="role-manage">${state.roles.roles.map(r=>`<div class="role-item"><span class="role-pill" style="--role-color:${r.color}">${E(r.name)}</span><span class="grow muted">${r.manage_channels?'Kanały · ':''}${r.manage_messages?'Moderacja · ':''}${r.view_private?'Prywatne':''}</span><button class="ghost" data-action="delete-role" data-id="${r.id}" title="Usuń rolę">${ic('close',15)}</button></div>`).join('')||'<p class="help">Nie utworzono jeszcze ról.</p>'}</div><button class="primary wide" data-action="new-role">${ic('plus',16)} Utwórz rolę</button><p class="help" style="margin-top:12px">Przypisywanie ról: kliknij ikonę ustawień przy członku po prawej stronie.</p>`);
}
function newRoleDialog(){openModal('Utwórz rolę',`<form data-form="new-role">${formInput('name','Nazwa roli','np. Moderator')}<div class="field"><label>Kolor roli</label><input type="color" name="color" value="#9b83f7" style="height:50px"></div><label class="checkboxline"><input type="checkbox" name="manage_channels"> Zarządzanie kanałami</label><label class="checkboxline"><input type="checkbox" name="manage_messages"> Usuwanie wiadomości członków</label><label class="checkboxline"><input type="checkbox" name="view_private"> Dostęp do prywatnych kanałów</label><div class="actions"><button type="submit" class="primary">Utwórz rolę</button></div></form>`)}
function assignRoleDialog(uid){const member=state.members.find(m=>m.id===uid);if(!member)return;openModal('Role: '+member.display_name,`<p class="muted" style="margin-bottom:15px">Zaznacz role przyznane temu użytkownikowi.</p><div class="role-manage">${state.roles.roles.map(r=>`<label class="role-item"><input type="checkbox" class="assign-check" data-user="${uid}" data-role="${r.id}" ${(member.custom_roles||[]).includes(r.id)?'checked':''}><span class="role-pill" style="--role-color:${r.color}">${E(r.name)}</span></label>`).join('')||'<p class="help">Najpierw utwórz rolę.</p>'}</div><div class="actions"><button class="primary" data-action="close-modal">Gotowe</button></div>`)}
const previousAction=handleAction;
handleAction=async function(el){const a=el.dataset.action,id=Number(el.dataset.id);
 try{
  if(a==='open-channel'){state.channelId=id;state.draft='';state.showChannels=false;await refresh();return}
  if(a==='toggle-channels'){state.showChannels=!state.showChannels;draw();return}
  if(a==='new-channel'){newChannelDialog();return}
  if(a==='edit-channel'){newChannelDialog(state.channels.find(x=>x.id===id));return}
  if(a==='delete-channel'){if(confirm('Zarchiwizować kanał? Jego historia zostanie bezpiecznie ukryta.')){await api(`/rooms/${state.roomId}/channels/${id}`,{method:'DELETE'});closeModal();await refresh();toast('Kanał zarchiwizowany.')}return}
  if(a==='server-settings'){serverSettingsDialog();return}
  if(a==='show-rules'){const s=state.studio?.config;openModal('Regulamin serwera',`<div class="rules-content">${E(s?.rules||'Regulamin nie został jeszcze dodany.')}</div><p class="help" style="margin-top:16px">Przestrzegaj zasad społeczności i dbaj o bezpieczeństwo innych.</p>`);return}
  if(a==='manage-roles'){rolesDialog();return}
  if(a==='new-role'){newRoleDialog();return}
  if(a==='assign-role'){assignRoleDialog(id);return}
  if(a==='delete-role'){if(confirm('Usunąć rolę i przypisania?')){await api(`/rooms/${state.roomId}/roles/${id}`,{method:'DELETE'});closeModal();await refresh();rolesDialog()}return}
  if(a==='delete-profile-media'){
    const kind=el.dataset.id;
    if(!['avatar','banner'].includes(kind))return;
    await api('/me/media/'+kind,{method:'DELETE'});
    closeModal();await refresh();toast(kind==='avatar'?'Usunięto zdjęcie profilowe.':'Usunięto baner.');return;
  }
  if(a==='set-theme'){state.theme=el.dataset.id;safeStore.setItem('vilo_theme',state.theme);applyAppearance();draw();return}
  if(a==='set-accent'){state.accent=el.dataset.id;safeStore.setItem('vilo_accent',state.accent);applyAppearance();draw();return}
  if(a==='new-poll'&&state.rooms.find(r=>r.id===state.roomId)?.kind==='server'&&state.channels.find(c=>c.id===state.channelId)?.kind==='voice'){return toast('Ankiety tworzy się na kanałach tekstowych.',true)}
 }catch(e){toast(e.message,true);return}
 return previousAction(el)
};
const previousForm=handleForm;
handleForm=async function(e){const form=e.target.closest('form[data-form]');if(!form)return;
 const t=form.dataset.form;const fd=new FormData(form);const val=k=>String(fd.get(k)||'').trim();
 if(['new-channel','edit-channel','server-settings','new-role'].includes(t)){
  e.preventDefault();try{
   if(t==='new-channel'||t==='edit-channel'){
     const body={name:val('name'),category:val('category'),kind:val('kind'),staff_only:!!fd.get('staff_only')};
     const url=`/rooms/${state.roomId}/channels${t==='edit-channel'?'/'+form.dataset.id:''}`;
     const result=await api(url,{method:t==='new-channel'?'POST':'PATCH',body});
     if(result.id)state.channelId=result.id;
   }else if(t==='server-settings')await api(`/rooms/${state.roomId}/studio`,{method:'PATCH',body:{name:val('name'),description:val('description'),rules:val('rules'),welcome:val('welcome'),accent:val('accent')}});
   else await api(`/rooms/${state.roomId}/roles`,{method:'POST',body:{name:val('name'),color:val('color'),manage_channels:!!fd.get('manage_channels'),manage_messages:!!fd.get('manage_messages'),view_private:!!fd.get('view_private')}});
   closeModal();await refresh();toast('Zapisano zmiany.');
  }catch(err){toast(err.message,true)}return;
 }
 if(['message','new-poll'].includes(t)){
  e.preventDefault();try{
   const r=state.rooms.find(x=>x.id===state.roomId);const cid=r?.kind==='server'?state.channelId:null;
   if(t==='message'){
     const msg=val('body')||val('message')||state.draft.trim();if(!msg)return;
     await api(`/rooms/${state.roomId}/messages`,{method:'POST',body:{body:msg,channel_id:cid}});state.draft='';
   }else{
     const opts=val('options').split('\n').map(x=>x.trim()).filter(Boolean);
     await api(`/rooms/${state.roomId}/polls`,{method:'POST',body:{question:val('question'),options:opts,multiple:!!fd.get('multiple'),anonymous:!!fd.get('anonymous'),channel_id:cid}});
     closeModal();
   }
   await refresh();if(t==='new-poll')toast('Ankieta utworzona.');
  }catch(err){toast(err.message,true)}return;
 }
 return previousForm(e)
};
document.addEventListener('change',async e=>{
 if(e.target.id==='toggle-compact'){state.compact=e.target.checked;safeStore.setItem('vilo_compact',state.compact?'1':'0');applyAppearance()}
 if(e.target.classList.contains('assign-check')){const t=e.target;try{await api(`/rooms/${state.roomId}/roles/${t.dataset.role}/users/${t.dataset.user}`,{method:'POST',body:{assigned:t.checked}});await refresh(false);toast('Uprawnienia zapisane.')}catch(err){t.checked=!t.checked;toast(err.message,true)}}
},true);

mount();boot().catch(()=>authScreen());
